package br.com.devedores.app;
import android.app.*;import android.content.*;import android.os.*;
public class LoanAlarmReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent in){String type=in.getStringExtra("type");String id=in.getStringExtra("id");String title=in.getStringExtra("title");NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel="devedores_alertas";if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(channel,"Devedores • Alertas",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Vencimentos e lembretes");ch.enableVibration(true);nm.createNotificationChannel(ch);}Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,Math.abs((id+":"+in.getIntExtra("index",-1)).hashCode()),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String head="loan".equals(type)?"Vencimento de parcela":"Lembrete do Devedores";Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,channel):new Notification.Builder(c);b.setSmallIcon(br.com.devedores.app.R.drawable.ic_notification).setContentTitle(head).setContentText(title==null?"Você tem um alerta":title).setAutoCancel(true).setContentIntent(pi).setPriority(Notification.PRIORITY_HIGH).setVibrate(new long[]{0,300,200,500});nm.notify(Math.abs((id+":"+in.getIntExtra("index",-1)).hashCode()),b.build());}
}
